import { useEffect, useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'completed' | 'over-quota';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  quotaPercent: number;
}

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'В работе',
  paused: 'Приостановлен',
  completed: 'Завершён',
  'over-quota': 'Превышен лимит',
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'paused', 'completed', 'over-quota'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн лендинга', status: 'active', quotaPercent: 42 },
  { id: 'p2', name: 'Миграция на новый биллинг', status: 'over-quota', quotaPercent: 118 },
  { id: 'p3', name: 'Внутренний портал', status: 'paused', quotaPercent: 67 },
  { id: 'p4', name: 'Мобильное приложение', status: 'active', quotaPercent: 25 },
  { id: 'p5', name: 'Аналитика продаж', status: 'completed', quotaPercent: 100 },
  { id: 'p6', name: 'Каталог поставщиков', status: 'active', quotaPercent: 88 },
  { id: 'p7', name: 'Автотесты API', status: 'paused', quotaPercent: 12 },
  { id: 'p8', name: 'Обновление CRM', status: 'over-quota', quotaPercent: 132 },
  { id: 'p9', name: 'Дашборд поддержки', status: 'active', quotaPercent: 54 },
  { id: 'p10', name: 'Импорт склада', status: 'completed', quotaPercent: 96 },
  { id: 'p11', name: 'Интеграция с платежами', status: 'paused', quotaPercent: 39 },
  { id: 'p12', name: 'Отчёты по маркетингу', status: 'active', quotaPercent: 71 },
];

const PAGE_SIZE = 5;
const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

function CircularQuota({ value }: { value: number }) {
  const clamped = Math.min(100, Math.max(0, value));
  const offset = CIRCUMFERENCE - (clamped / 100) * CIRCUMFERENCE;
  const isOver = value > 100;

  return (
    <svg
      className="jx-progress-ring"
      width="40"
      height="40"
      viewBox="0 0 40 40"
      role="img"
      aria-label={`Заполнение квоты: ${value}%`}
    >
      <circle
        className="jx-progress-ring__track"
        cx="20"
        cy="20"
        r={RADIUS}
        fill="none"
        strokeWidth="4"
        style={{ stroke: 'var(--jx-color-border)' }}
      />
      <circle
        className="jx-progress-ring__value"
        cx="20"
        cy="20"
        r={RADIUS}
        fill="none"
        strokeWidth="4"
        strokeLinecap="round"
        strokeDasharray={CIRCUMFERENCE}
        strokeDashoffset={offset}
        style={{
          stroke: isOver ? 'var(--jx-color-danger)' : 'var(--jx-color-primary)',
          transform: 'rotate(-90deg)',
          transformOrigin: '50% 50%',
        }}
      />
      <text
        x="20"
        y="24"
        textAnchor="middle"
        className="jx-progress-ring__text"
        style={{ fill: 'var(--jx-color-fg)' }}
      >
        {value}%
      </text>
    </svg>
  );
}

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));

  useEffect(() => {
    setPage(1);
  }, [activeStatuses]);

  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [page, totalPages]);

  const pageItems = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((s) => s !== status));
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
  };

  return (
    <section className="jx-panel">
      <h2 className="jx-panel__title">Расход по проектам</h2>

      <div className="jx-chip-row" role="list" aria-label="Фильтры по статусу">
        {activeStatuses.length === 0 ? (
          <span className="jx-chip-row__empty">Фильтры не выбраны</span>
        ) : (
          activeStatuses.map((status) => (
            <span key={status} className="jx-chip" role="listitem">
              <span className="jx-chip__label">{STATUS_LABELS[status]}</span>
              <button
                type="button"
                className="jx-chip__remove"
                onClick={() => removeStatus(status)}
                aria-label={`Убрать фильтр «${STATUS_LABELS[status]}»`}
              >
                ×
              </button>
            </span>
          ))
        )}
      </div>

      {filtered.length === 0 ? (
        <div className="jx-empty-state">
          <p className="jx-empty-state__text">Нет проектов по выбранным фильтрам</p>
          <Button onClick={resetFilters}>Сбросить фильтры</Button>
        </div>
      ) : (
        <>
          <ul className="jx-list">
            {pageItems.map((project) => (
              <li key={project.id} className="jx-list__row">
                <span className="jx-list__name">{project.name}</span>
                <CircularQuota value={project.quotaPercent} />
                <span className={`jx-badge jx-badge--${project.status}`}>
                  {STATUS_LABELS[project.status]}
                </span>
              </li>
            ))}
          </ul>

          <nav className="jx-pagination" aria-label="Пагинация списка проектов">
            <Button
              variant="ghost"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Назад
            </Button>
            <span className="jx-pagination__status">
              {page} / {totalPages}
            </span>
            <Button
              variant="ghost"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            >
              Далее
            </Button>
          </nav>
        </>
      )}
    </section>
  );
}

